import numpy as np
from scipy import stats
from sklearn.metrics import roc_auc_score
from sklearn.feature_selection import mutual_info_classif
from collections import defaultdict

MAX_DRIVERS = 5

def design(feats):
    # Identify strong candidates based on t-statistics and AUC
    strong_candidates = []
    for i, fid in enumerate(feats.ids):
        if feats.types[i] != 'derived':
            # Compute t-statistic manually
            x_col = feats.x[:, feats.column(fid)]
            mean_y1 = np.mean(x_col[feats.y == 1])
            mean_y0 = np.mean(x_col[feats.y == 0])
            t_stat = (mean_y1 - mean_y0) / (np.std(x_col) + 1e-8)
            auc = roc_auc_score(feats.y, x_col)
            strong_candidates.append((fid, abs(t_stat), auc))

    # Sort by t-statistic
    strong_candidates.sort(key=lambda x: x[1], reverse=True)

    # Remove near-duplicates based on correlation
    to_remove = set()
    if len(feats.ids) > 1:
        corr_matrix = np.corrcoef(feats.x.T)
        for i in range(len(feats.ids)):
            for j in range(i+1, len(feats.ids)):
                if abs(corr_matrix[i,j]) >= 0.6:
                    # Keep the one with higher absolute t-statistic
                    if i < len(strong_candidates) and j < len(strong_candidates):
                        fid_i, t_i, _ = strong_candidates[i]
                        fid_j, t_j, _ = strong_candidates[j]
                        if t_i < t_j:
                            to_remove.add(fid_i)
                        else:
                            to_remove.add(fid_j)

    # Filter out near-duplicates
    filtered_candidates = [c for c in strong_candidates if c[0] not in to_remove]

    # Select top drivers (at most MAX_DRIVERS)
    drivers = tuple(c[0] for c in filtered_candidates[:MAX_DRIVERS])

    # Build columns list - include all non-derived features
    columns = tuple(fid for fid in feats.ids if feats.types[feats.column(fid)] != 'derived')

    # Build products - consider pairs with high correlation
    products = []
    if len(feats.ids) > 1:
        corr_matrix = np.corrcoef(feats.x.T)
        for i in range(len(feats.ids)):
            for j in range(i+1, len(feats.ids)):
                if abs(corr_matrix[i,j]) >= 0.6:
                    fid_i, fid_j = feats.ids[i], feats.ids[j]
                    if (fid_i, fid_j) not in products and (fid_j, fid_i) not in products:
                        products.append((fid_i, fid_j))

    # Build loadings - use weighted sum of top features
    loadings = {}
    for i, (fid, _, _) in enumerate(filtered_candidates[:5]):
        loadings[fid] = 1.0 / (i + 1)

    return Design(drivers=drivers, columns=columns, products=tuple(products), loadings=loadings)
